// === MINEBENCH: CHOo-CHOo TRAIN ===
// Steam locomotive + tender + 2 passenger cars + track + station + water tower + trees + smoke
// Tracks along x-axis at z=128, train faces +x, station on -z side

// --- Helpers ---
function ring(cx,cy,cz,rx,rz,type){
  for(let a=-rx;a<=rx;a++) for(let c=-rz;c<=rz;c++){
    if(a*a/(rx*rx)+c*c/(rz*rz)>=0.65 && a*a/(rx*rx)+c*c/(rz*rz)<=1.1){
      block(cx+a,cy,cz+c,type);
    }
  }
}

// --- CONSTANTS ---
const TRACK_Z=128;
const WB=10;
const BCTR=16;
const BR=6;
const LFX=175;
const LFR=140;
const CAB_B=112;
const TEND_F=111, TEND_B=80;
const PC1_F=79, PC1_B=50;
const PC2_F=49, PC2_B=20;
const STX1=185, STX2=215, STZ1=100, STZ2=135;
const WT_X=170, WT_Z=105;

// --- 1. TERRAIN ---
for(let x=30;x<220;x++) for(let z=55;z<200;z++){
  if((x*7+z*13)%17===0) block(x,5,z,"grass_block");
  else if((x*3+z*11)%23===0) block(x,5,z,"sand");
  else block(x,5,z,"dirt");
  block(x,4,z,"dirt");
}

// --- 2. TRACK ---
for(let x=35;x<210;x++) for(let z=122;z<134;z++) block(x,5,z,"cobblestone");
for(let x=35;x<210;x++){ block(x,6,124,"iron_block"); block(x,6,131,"iron_block"); }
for(let x=38;x<210;x+=3) box(x,5,123,x,5,132,"oak_log");

// --- 3. LOCOMOTIVE ---
for(let z of [125,131]) box(LFR,WB-1,z,LFX,WB-1,z,"iron_block");
for(let x=LFR;x<=LFX;x+=4) box(x,WB-1,123,x,WB-1,133,"iron_block");

// Boiler - horizontal cylinder along x
for(let x=LFR;x<=LFX;x++){
  for(let y=BCTR-BR;y<=BCTR+BR;y++){
    const r=Math.round(Math.sqrt(Math.max(0,BR*BR-(y-BCTR)*(y-BCTR))));
    for(let dz=-r;dz<=r;dz++){ block(x,y,TRACK_Z+dz,"gray_wool"); block(x,y,TRACK_Z-dz,"gray_wool"); }
  }
}
// Conical front
for(let x=LFX-12;x<=LFX;x++){
  const t=(x-(LFX-12))/12;
  const cr=Math.max(3,Math.round(BR-t*(BR-4)));
  for(let y=BCTR-cr;y<=BCTR+cr;y++){
    const r=Math.round(Math.sqrt(Math.max(0,cr*cr-(y-BCTR)*(y-BCTR))));
    for(let dz=-r;dz<=r;dz++) block(x,y,TRACK_Z+dz,"gray_wool");
  }
}
// Iron bands
for(let bx of [LFR+12,LFR+30,LFX-8]){
  for(let y=BCTR-BR+1;y<=BCTR+BR-1;y++){
    const r=Math.round(Math.sqrt(Math.max(0,BR*BR-(y-BCTR)*(y-BCTR))));
    if(r>1){ block(bx,y,TRACK_Z+r,"iron_block"); block(bx,y,TRACK_Z-r,"iron_block"); }
  }
}

// Smokestack
for(let y=BCTR+BR;y<=BCTR+BR+12;y++){
  const r=y<=BCTR+BR+3?4:y<=BCTR+BR+6?3:2;
  for(let dx=-r;dx<=r;dx++) for(let dz=-r;dz<=r;dz++){
    if(dx*dx+dz*dz<=r*r) block(LFX-6+dx,y,TRACK_Z+3+dz,"black_wool");
  }
}
ring(LFX-6,BCTR+BR+13,TRACK_Z+3,4,4,"iron_block");

// Dome
ring(LFR+25,BCTR+BR-1,TRACK_Z,3,3,"gold_block");
for(let dx=-1;dx<=1;dx++) for(let dz=-1;dz<=1;dz++){
  if(dx*dx+dz*dz<=2) block(LFR+25+dx,BCTR+BR,TRACK_Z+dz,"gold_block");
}

// Bell
box(LFR+30,BCTR-2,TRACK_Z-1,LFR+33,BCTR+1,TRACK_Z+1,"gold_block");
block(LFR+32,BCTR+2,TRACK_Z,"gold_block");

// Headlight
box(LFX-1,BCTR-3,TRACK_Z-2,LFX-1,BCTR,TRACK_Z+2,"glowstone");
ring(LFX-2,BCTR-1,TRACK_Z,2,2,"iron_block");

// Cowcatcher
for(let y=WB-3;y<=WB+1;y++){
  const w=3+Math.max(0,Math.floor((WB+1-y)*1.2));
  box(LFX+1,y,TRACK_Z-w,LFX+3+Math.max(0,8-y),y,TRACK_Z+w,"iron_block");
}
for(let y=WB-3;y<=WB+1;y++){
  const w=3+Math.max(0,Math.floor((WB+1-y)*1.2));
  box(LFX+1,y,TRACK_Z-w,LFX+1,y,TRACK_Z+w,"bricks");
}

// Cab
box(141,WB-1,CAB_B,141,BCTR+BR-1,TRACK_Z-5,"oak_planks");
box(141,WB-1,CAB_B,141,WB-1,TRACK_Z-5,"oak_planks");
for(let x=140;x>=CAB_B;x--){
  const t=(140-x)/(140-CAB_B);
  const rh=3+Math.round(Math.sin(t*Math.PI)*3);
  box(x,BCTR+BR-1,TRACK_Z-6,x,BCTR+BR-1+rh,TRACK_Z+1,"bricks");
}
for(let x=138;x>=132;x--){
  block(x,BCTR-2,TRACK_Z-5,"glass"); block(x,BCTR-1,TRACK_Z-5,"glass"); block(x,BCTR,TRACK_Z-5,"glass");
  block(x,BCTR-2,TRACK_Z+1,"glass"); block(x,BCTR-1,TRACK_Z+1,"glass"); block(x,BCTR,TRACK_Z+1,"glass");
}
box(CAB_B,WB,TRACK_Z-4,CAB_B,WB+3,TRACK_Z-2,"oak_planks");

// --- 4. WHEELS ---
const dwx=[LFX-14,LFR+10,LFR+28];
for(const wx of dwx){
  for(let dy=-5;dy<=5;dy++) for(let dz=-5;dz<=5;dz++){
    if(dy*dy+dz*dz<=28 && dy*dy+dz*dz>=18){ block(wx,WB+dy,TRACK_Z+dz,"iron_block"); block(wx,WB+dy,TRACK_Z-dz,"iron_block"); }
  }
  block(wx,WB,TRACK_Z,"iron_block"); block(wx,WB,TRACK_Z-3,"iron_block");
  for(let s=0;s<8;s++){
    const a=s*Math.PI/4;
    for(let rr=2;rr<=4;rr++){
      block(wx,WB+Math.round(Math.cos(a)*rr),TRACK_Z+Math.round(Math.sin(a)*rr),"gray_wool");
      block(wx,WB+Math.round(Math.cos(a)*rr),TRACK_Z-Math.round(Math.sin(a)*rr),"gray_wool");
    }
  }
}
for(let x=dwx[2];x<=dwx[0];x++){ block(x,WB+4,TRACK_Z+2,"iron_block"); block(x,WB+4,TRACK_Z-5,"iron_block"); }

// Pistons
box(LFX-10,WB-3,TRACK_Z-2,LFX-6,WB,TRACK_Z+1,"iron_block");
box(LFX-10,WB-3,TRACK_Z-5,LFX-6,WB,TRACK_Z-2,"iron_block");
for(let x=LFX-10;x<=dwx[2];x++) block(x,WB+2,TRACK_Z,"iron_block");

// --- 5. TENDER ---
box(TEND_F,WB-1,TEND_B,TEND_B,WB+6,TEND_B,"oak_planks");
for(let x=TEND_F+2;x<=TEND_B-3;x++){
  for(let y=WB+1;y<=WB+5;y++){
    const hw=3+Math.max(0,Math.floor((4-Math.abs(x-(TEND_F+TEND_B)/2)/12)));
    for(let z=TEND_B+1;z<=TEND_B+hw;z++) block(x,y,z,"black_wool");
  }
}
for(const wx of [TEND_F+4,TEND_B+8]){
  for(let dy=-3;dy<=3;dy++) for(let dz=-3;dz<=3;dz++){
    if(dy*dy+dz*dz<=11 && dy*dy+dz*dz>=5){ block(wx,WB+dy,TRACK_Z+dz,"iron_block"); block(wx,WB+dy,TRACK_Z-dz,"iron_block"); }
  }
}
box(TEND_F+2,WB+7,TEND_B+3,TEND_B-5,WB+7,TEND_B-2,"oak_planks");

// --- 6. PASSENGER CARS ---
function buildPassCar(fX,rX){
  box(fX,WB-1,rX,fX,WB+7,rX,"white_wool");
  for(let x=fX;x>=rX;x--){
    const t=(fX-x)/(fX-rX);
    const rh=2+Math.round(Math.sin(t*Math.PI)*2);
    box(x,WB+7,TRACK_Z-3,x,WB+7+rh,TRACK_Z+4,"bricks");
  }
  box(fX,WB,TRACK_Z-1,fX,WB+1,TRACK_Z+5,"red_wool");
  for(let x=fX-2;x>=rX+3;x-=3){
    block(x,WB+3,TRACK_Z,"glass"); block(x,WB+4,TRACK_Z,"glass");
    block(x,WB+3,TRACK_Z-1,"glass"); block(x,WB+4,TRACK_Z-1,"glass");
    block(x,WB+3,TRACK_Z+4,"glass"); block(x,WB+4,TRACK_Z+4,"glass");
  }
  box(fX-5,WB,TRACK_Z-1,fX-5,WB+3,TRACK_Z,"oak_planks");
  box(fX-5,WB,TRACK_Z+3,fX-5,WB+3,TRACK_Z+4,"oak_planks");
  for(const wx of [fX-3,rX+5]){
    for(let dy=-3;dy<=3;dy++) for(let dz=-3;dz<=3;dz++){
      if(dy*dy+dz*dz<=11 && dy*dy+dz*dz>=5){ block(wx,WB+dy,TRACK_Z+dz,"iron_block"); block(wx,WB+dy,TRACK_Z-dz,"iron_block"); }
    }
  }
}
buildPassCar(PC1_F,PC1_B);
buildPassCar(PC2_F,PC2_B);

// --- 7. STATION PLATFORM ---
box(188,6,106,212,6,142,"stone_bricks");
box(188,6,106,212,6,109,"oak_planks");
box(188,5,106,212,5,109,"stone_bricks");
box(188,4,106,212,4,109,"stone");

// --- 8. STATION BUILDING ---
box(STX1,5,STZ1,STX2,5,STZ2,"stone_bricks");
box(STX1,6,STZ1,STX2,14,STZ1,"bricks");
box(STX1,6,STZ2,STX2,14,STZ2,"bricks");
box(STX1,6,STZ1,STX1,14,STZ2,"bricks");
box(STX2,6,STZ1,STX2,14,STZ2,"bricks");
box(STX1,6,STZ1,STX2,14,STZ2,"bricks");
box(STX1+12,6,STZ2-1,STX1+14,10,STZ2,"oak_planks");
for(let wx of [STX1+6,STX1+18]) box(wx,8,STZ2-1,wx,10,STZ2,"glass");
for(let x=STX1-3;x<=STX2+3;x++){
  const cx=(STX1+STX2)/2, dist=Math.abs(x-cx), roofH=17-Math.round(dist/7);
  box(x,roofH,STZ1-2,x,roofH,STZ2+2,"bricks");
}
box(STX1-3,17,STZ1-2,STX2+3,17,STZ1-2,"gold_block");
box(STX1-3,17,STZ2+2,STX2+3,17,STZ2+2,"gold_block");
box(STX1+10,12,STZ2-1,STX1+16,13,STZ2-1,"oak_planks");
box(STX1+12,18,STZ1,STX1+14,22,STZ1,"bricks");
box(STX1+11,18,STZ1-1,STX1+15,18,STZ1+1,"gold_block");
box(STX1+11,23,STZ1,STX1+15,23,STZ1,"bricks");
ring(STX1+13,24,STZ1,1,1,"gold_block");

// --- 9. WATER TOWER ---
box(WT_X-1,6,WT_Z-1,WT_X-1,20,WT_Z-1,"oak_log");
box(WT_X+4,6,WT_Z-1,WT_X+4,20,WT_Z-1,"oak_log");
box(WT_X-1,6,WT_Z+4,WT_X-1,20,WT_Z+4,"oak_log");
box(WT_X+4,6,WT_Z+4,WT_X+4,20,WT_Z+4,"oak_log");
box(WT_X-1,10,WT_Z-1,WT_X+4,10,WT_Z-1,"oak_log");
box(WT_X-1,14,WT_Z-1,WT_X+4,14,WT_Z-1,"oak_log");
for(let y=20;y<=26;y++){
  const r=y<=21?4:y<=24?3:2;
  for(let dx=-r;dx<=r;dx++) for(let dz=-r;dz<=r;dz++){
    if(dx*dx+dz*dz<=r*r) block(WT_X+dx,y,WT_Z+dz,"iron_block");
  }
}
for(let dx=-2;dx<=2;dx++) for(let dz=-2;dz<=2;dz++){
  if(dx*dx+dz*dz<=5) block(WT_X+dx,27,WT_Z+dz,"bricks");
}
ring(WT_X,23,WT_Z,3,3,"iron_block");

// --- 10. TREES ---
function tree(tx,ty,tz){
  for(let y=0;y<6;y++) block(tx,ty+y,tz,"oak_log");
  for(let dx=-3;dx<=3;dx++) for(let dy=-2;dy<=3;dy++) for(let dz=-3;dz<=3;dz++){
    if(dx*dx+dy*dy/2+dz*dz<=11) block(tx+dx,ty+6+dy,tz+dz,"oak_leaves");
  }
}
tree(50,5,80); tree(60,5,160); tree(200,5,70); tree(210,5,170);
tree(150,5,155); tree(140,5,75); tree(80,5,150); tree(90,5,70);
tree(110,5,165); tree(195,5,160); tree(45,5,130);

// --- 11. SMOKE ---
for(let i=0;i<80;i++){
  const sx=LFX-6+Math.round((i%7)-3+(rng()-0.5)*3);
  const sy=BCTR+BR+14+Math.round(i/7)+Math.round(rng()*4);
  const sz=TRACK_Z+3+Math.round((i%5)-2+(rng()-0.5)*3);
  block(sx,sy,sz,i%3===0?"gray_wool":"white_wool");
}

// --- 12. DETAILS ---
box(186,6,110,186,8,110,"oak_planks");
box(185,6,111,185,8,111,"oak_planks");
for(let lx of [190,196,202,208]){ block(lx,9,108,"glowstone"); block(lx,8,108,"iron_block"); block(lx,7,108,"oak_log"); }
box(193,6,112,196,6,115,"oak_planks");
box(201,6,112,204,6,115,"oak_planks");
box(187,6,116,187,8,118,"red_wool");
box(187,9,116,187,9,118,"oak_planks");
